package initdb

import (
	"sync"

	"github.com/goopg/goopg/internal/catalog"
	"github.com/goopg/goopg/internal/executor"
)

// pgTypeFullRow is a complete pg_type row (typdefaultbin/typdefault/typacl are
// NULL for every row it carries) as a PostgreSQL 18.3 initdb holds it, plus the
// name of the relation a rowtype belongs to (pgTypeInitdbRowtypes, generated by
// scripts/gen-pg-type-rowtypes.py). M0149-0001g slice 18.
type pgTypeFullRow struct {
	OID                          uint32
	Name                         string
	Nsp                          uint32
	Len                          int16
	ByVal                        bool
	Type, Category               byte
	Preferred, Defined           bool
	Delim                        byte
	RelID                        uint32
	RelName                      string
	Subscript, Elem, Array       uint32
	Input, Output, Receive, Send uint32
	ModIn, ModOut, Analyze       uint32
	Align, Storage               byte
	NotNull                      bool
	BaseType                     uint32
	TypMod, NDims                int32
	Collation                    uint32
}

// pgTypeRowtypeRows returns the captured rowtype rows goopg adds to its
// bootstrap pg_type: a rowtype whose relation goopg bootstraps under the same
// OID and name, and the array type of each accepted rowtype — minus any OID
// goopg's own table already writes. Keyed by OID.
var pgTypeRowtypeRows = sync.OnceValue(func() map[uint32]pgTypeFullRow {
	rels := pgBootstrapRelNameByOID()
	have := pgTypeBootstrapEntryMap()
	accepted := map[uint32]pgTypeFullRow{}
	for _, r := range pgTypeInitdbRowtypes {
		if r.RelID != 0 && rels[r.RelID] == r.RelName {
			accepted[r.OID] = r
		}
	}
	for _, r := range pgTypeInitdbRowtypes {
		if r.RelID == 0 {
			if _, ok := accepted[r.Elem]; ok {
				accepted[r.OID] = r
			}
		}
	}
	for oid := range accepted {
		if _, dup := have[oid]; dup {
			delete(accepted, oid)
		}
	}
	return accepted
})

// pgClassRowtypeOID is the rowtype OID PG gives relation relOID, from the
// captured rows (0 when there is none).
var pgClassRowtypeOIDs = sync.OnceValue(func() map[uint32]uint32 {
	rels := pgBootstrapRelNameByOID()
	m := map[uint32]uint32{}
	for _, r := range pgTypeInitdbRowtypes {
		if r.RelID != 0 && rels[r.RelID] == r.RelName {
			m[r.RelID] = r.OID
		}
	}
	return m
})

func pgTypeFullRowDatums(r pgTypeFullRow) executor.Row {
	i := func(v int64) executor.Datum { return executor.NewIntDatum(v) }
	c := func(b byte) executor.Datum { return executor.NewStringDatum(string(rune(b))) }
	return executor.Row{
		i(int64(r.OID)), executor.NewStringDatum(r.Name), i(int64(r.Nsp)), i(10), i(int64(r.Len)),
		executor.NewBoolDatum(r.ByVal), c(r.Type), c(r.Category), executor.NewBoolDatum(r.Preferred),
		executor.NewBoolDatum(r.Defined), c(r.Delim), i(int64(r.RelID)), i(int64(r.Subscript)), i(int64(r.Elem)),
		i(int64(r.Array)), i(int64(r.Input)), i(int64(r.Output)), i(int64(r.Receive)), i(int64(r.Send)),
		i(int64(r.ModIn)), i(int64(r.ModOut)), i(int64(r.Analyze)), c(r.Align), c(r.Storage),
		executor.NewBoolDatum(r.NotNull), i(int64(r.BaseType)), i(int64(r.TypMod)), i(int64(r.NDims)),
		i(int64(r.Collation)), executor.NullDatum, executor.NullDatum, executor.NullDatum,
	}
}

// Register the system relation → rowtype map for the virtual pg_class
// renderer's reltype column. M0149-0001h1a34.
func init() { catalog.SetBuiltinRelTypes(pgClassRowtypeOIDs()) }
